/// <reference path="../pb_data/types.d.ts" />
// Schema guards: serve re-asserts migration-defined field patterns; app_docs refuses unknown body keys.

onBootstrap((e) => {
  e.next();
  // onServe, never onBootstrap itself: on a fresh DB bootstrap runs BEFORE migrations (measured:
  // 8 applied, app_docs absent), so the collections this restores do not exist there yet.
  $app.onServe().bindFunc((se) => {
    // Generated by scripts/gen_schema.ts from the same replayed migrations as schema/, so a
    // migration that changes a pattern moves this file with it; schema/ reaches no container.
    let patterns = null;
    try {
      patterns = JSON.parse(
        toString($os.readFile(__hooks + "/field_patterns.json")),
      );
    } catch (err) {
      // Restoring from a half-known map could revert a migration, so an unusable file restores
      // nothing at all — and never stops the server from binding.
      se.app
        .logger()
        .error(
          "schema_guards: field_patterns.json unreadable, patterns not restored",
          "error",
          String(err),
        );
      return se.next();
    }
    for (const name in patterns) {
      // A superuser can delete a collection or field at runtime, so absence is logged, never
      // thrown: a throw here would stop the server from ever binding.
      try {
        let collection = null;
        try {
          collection = se.app.findCollectionByNameOrId(name);
        } catch (_) {
          se.app
            .logger()
            .error(
              "schema_guards: collection missing, pattern not restored",
              "collection",
              name,
            );
          continue;
        }
        let changed = false;
        for (const field in patterns[name]) {
          const f = collection.fields.getByName(field);
          if (!f) {
            se.app
              .logger()
              .error(
                "schema_guards: field missing, pattern not restored",
                "collection",
                name,
                "field",
                field,
              );
            continue;
          }
          if (f.pattern !== patterns[name][field]) {
            f.pattern = patterns[name][field];
            changed = true;
          }
        }
        // Forward-only: rows written while the pattern was widened stay as they are.
        if (changed) {
          se.app.save(collection);
          se.app
            .logger()
            .warn("schema_guards: restored field patterns", "collection", name);
        }
      } catch (err) {
        se.app
          .logger()
          .error(
            "schema_guards: pattern restore failed",
            "collection",
            name,
            "error",
            String(err),
          );
      }
    }
    return se.next();
  });
});

// A self-contained top-level fn passed DIRECTLY as the handler is legal under the pooled-JSVM law.
function refuseUnknownKeys(e) {
  const body = e.requestInfo().body || {};
  const fields = e.record.collection().fields;
  const errors = {};
  const unknown = [];
  for (const key of Object.keys(body)) {
    if (fields.getByName(key)) continue;
    unknown.push(key);
    errors[key] = new ValidationError("validation_failed", "Unknown field.");
  }
  if (unknown.length) {
    throw new BadRequestError(
      "Unknown field: " + unknown.join(", ") + ".",
      errors,
    );
  }
  return e.next();
}

onRecordCreateRequest(refuseUnknownKeys, "app_docs");
onRecordUpdateRequest(refuseUnknownKeys, "app_docs");
